// Generates website/src/content/docs/changelog.mdx from the repo-root CHANGELOG.md.
// Single source of truth: edit CHANGELOG.md, then `pnpm run build` (prebuild regenerates this).
// Do NOT hand-edit the generated file.
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const here = import.meta.dirname;
// Overridable for the regression tests (website/scripts/test/); production uses the repo root.
const sourcePath = resolve(process.env.CHANGELOG_SOURCE ?? resolve(here, "../../CHANGELOG.md"));
const targetPath = resolve(process.env.CHANGELOG_TARGET ?? resolve(here, "../src/content/docs/changelog.mdx"));

const raw = readFileSync(sourcePath, "utf8");

// The changelog is plain markdown, but the file is .mdx, where a bare '<' starts a
// JSX tag and breaks the build. Escape any '<' as an HTML char ref. ('>' is harmless
// in markdown text.) Guards against future entries that include angle brackets.
const safe = raw.replaceAll("<", "&lt;");

// Strip the leading "# Changelog" H1 — Starlight's frontmatter title is the page's H1.
const body = safe.replace(/^#\s+Changelog\s*\n+/u, "");

const output = `---
title: Changelog
description: All notable changes to go-atomic-write, generated from the root CHANGELOG.md.
---

{/* GENERATED by scripts/sync-changelog.mjs from ../../CHANGELOG.md. Do not edit by hand. Edit CHANGELOG.md and run \`pnpm run build\` (or \`pnpm run sync:changelog\`). */}

${body}`;

writeFileSync(targetPath, output, "utf8");
console.log(`[sync-changelog] ${sourcePath} -> ${targetPath}`);
